    VectorSearch = new VectorSearch
    {
        Algorithms = new[]
        {
            new HnswVectorSearchAlgorithmConfiguration
            {
                Name = "hnsw-accuracy",
                Parameters = new HnswParameters
                {
                    Metric = "cosine",
                    M = 8,          // Higher M = better recall, more memory
                    EfConstruction = 200, // Higher = better graph quality, slower build
                    EfSearch = 100  // Search parameter: higher = better accuracy, slower query
                }
            },
            new HnswVectorSearchAlgorithmConfiguration
            {
                Name = "hnsw-speed",
                Parameters = new HnswParameters
                {
                    Metric = "cosine",
                    M = 4,            // Lower M = less memory, lower recall
                    EfConstruction = 100,
                    EfSearch = 50      // Lower search = faster but less accurate
                }
            }
        }
    }
};

