    }
};

public class VectorSearchService
{
    private readonly SearchClient _client;

    public async Task<SearchResults<Document>> SearchAsync(
        string query, string indexName, bool isCustomerFacing = false)
    {
        var options = new SearchOptions
        {
            // For customer-facing queries: maximize accuracy
            // For batch/recommendation: prioritize speed
            Size = isCustomerFacing ? 10 : 50,
            VectorSearch = new() // Override with query-specific parameters
            {
                Queries = new[]
                {
                    new VectorizableEmbedding (
                        await GenerateEmbeddingAsync(query), "contentVector")
                    {
                        // Higher k for customer queries
                        K = isCustomerFacing ? 50 : 100,
                        // Override algorithm parameters
                        Override = new VectorSearchAlgorithmOverride
                        {
                            Name = "hnsw-" + (isCustomerFacing ? "accuracy" : "speed")
                        }
                    }
                }
            }
        };

        return await _client.SearchAsync<Document>(query, options);
    }
}
